param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'serialization-info-typed-getter-dispatch-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('SelectedConverterSpy'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('main');$builder=$module.DefineType('SelectedConverterSpy',[Reflection.TypeAttributes]::Public);$builder.AddInterfaceImplementation([Runtime.Serialization.IFormatterConverter]);$null=$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$calls=$builder.DefineField('Calls',[int],[Reflection.FieldAttributes]::Public);$last=$builder.DefineField('Last',[string],[Reflection.FieldAttributes]::Public)
foreach($base in [Runtime.Serialization.IFormatterConverter].GetMethods()){$parameters=[type[]]@($base.GetParameters()|ForEach-Object ParameterType);$method=$builder.DefineMethod($base.Name,[Reflection.MethodAttributes]'Public,Virtual,Final,HideBySig,NewSlot',$base.ReturnType,$parameters);$label=$base.Name;if($base.Name -eq 'Convert'){$label+=if($parameters[1] -eq [type]){':Type'}else{':TypeCode'}};$il=$method.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,$label);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$last);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'converter sentinel');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$builder.DefineMethodOverride($method,$base)};$spyType=$builder.CreateType()
function NativeType($name){if($name -eq 'NullableInt32'){return ([object].Assembly.GetType('System.Nullable`1')).MakeGenericType([type[]]@([int]))};return [object].Assembly.GetType('System.'+$name,$true)}
function Actual($name){switch($name){'null'{return $null};'Boolean'{return [bool]$true};'Byte'{return [byte]42};'Char'{return [char]65};'DateTime'{return [DateTime]::new(0)};'Decimal'{return [decimal]42};'Double'{return [double]1.25};'Int16'{return [int16]-42};'Int32'{return [int]-42};'Int64'{return [long]-42};'SByte'{return [sbyte]-42};'Single'{return [single]1.25};'String'{return 'sentinel'};'UInt16'{return [uint16]42};'UInt32'{return [uint32]42};'UInt64'{return [uint64]42}}}
function Result($route,$value){if($null -eq $value){return $null};switch($route){'GetChar'{return ([int][char]$value).ToString()};'GetDateTime'{return $value.Ticks.ToString()};'GetDecimal'{return ([decimal]::GetBits($value)-join ',')};'GetBoolean'{return $value.ToString().ToLowerInvariant()};default{return $value.ToString()}}}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new()
foreach($actualType in $plan.actualTypes){foreach($declaredType in $plan.declaredTypes){foreach($route in $plan.routes){$spy=[Activator]::CreateInstance($spyType);$info=[Runtime.Serialization.SerializationInfo]::new([object],[Runtime.Serialization.IFormatterConverter]$spy);$value=Actual $actualType;$info.AddValue('value',$value,(NativeType $declaredType));$errorName='none';$errorMessage=$null;$hResult=0;$param=$null;$result=$null;try{$result=$info.GetType().GetMethod($route,[type[]]@([string])).Invoke($info,[object[]]@('value'));$result=Result $route $result}catch{$errorValue=$_.Exception;while($null -ne $errorValue.InnerException){$errorValue=$errorValue.InnerException};$errorName=$errorValue.GetType().FullName;$errorMessage=$errorValue.Message;$hResult=$errorValue.HResult;if($errorValue -is [ArgumentException]){$param=$errorValue.ParamName}};$rows.Add([ordered]@{actualType=$actualType;declaredType=$declaredType;route=$route;callbackCalls=$spy.Calls;callback=$spy.Last;resultUnits=(Units $result);exception=$errorName;messageUnits=(Units $errorMessage);hResult=$hResult;paramUnits=(Units $param);memberCount=$info.MemberCount})}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS declared getter dispatch: $($rows.Count) scenarios"
